# Proper calculation: BFS from all cells in a component to see which edges they can reach
from collections import deque

height, width = 15, 5

def compute_edges_for_component(cells, grid):
    """Return set of edges this component can reach via 0-paths"""
    reachable_edges = set()

    # For each cell, do BFS and check which borders are reachable
    for (start_r, start_c) in cells:
        visited = set([(start_r, start_c)])
        q = deque([(start_r, start_c)])

        while q:
            r, c = q.popleft()

            # Check which edge we're at
            if c == 0: reachable_edges.add('L')
            if c == width - 1: reachable_edges.add('R')
            if r == 0: reachable_edges.add('T')
            if r == height - 1: reachable_edges.add('B')

            for dr, dc in [(0,1),(0,-1),(1,0.),(-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width and (nr, nc) not in visited and grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    q.append((nr, nc))

    return reachable_edges

